int main() {
    std::mt19937 a{211};
    std::mt19937 b{211};
    std::uniform_int_distribution<int> tam_a{0, 4};
    std::uniform_int_distribution<int> tam_b{0, 4};
    std::uniform_int_distribution<int> val_a{0, 9};
    std::uniform_int_distribution<int> val_b{0, 9};
    bool iguales = true;
    for (int intento{0}; intento < 5; ++intento) {
        const int cantidad_a = tam_a(a);
        const int cantidad_b = tam_b(b);
        std::vector<int> uno;
        std::vector<int> dos;
        for (int i{0}; i < cantidad_a; ++i) {
            uno.push_back(val_a(a));
        }
        for (int i{0}; i < cantidad_b; ++i) {
            dos.push_back(val_b(b));
        }
        iguales = iguales && uno == dos;
    }
    std::cout << "Repeticion:" << iguales;
    return 0;
}

