#include <iostream>
#include <random>
#include <vector>
#include <stdexcept>

int contar_desde(const std::vector<int>& datos, int minimo) {
    int cantidad{0};
    for (int dato : datos) {
        if (dato >= minimo) {
            ++cantidad;
        }
    }
    return cantidad;
}

int esperado_por_descartes(const std::vector<int>& datos, int minimo) {
    int rechazados{0};
    for (int dato : datos) {
        if (dato < minimo) {
            ++rechazados;
        }
    }
    return static_cast<int>(datos.size()) - rechazados;
}

bool verificar(const std::vector<int>& datos, int minimo, int esperado) {
    const int real = contar_desde(datos, minimo);
    return real == esperado;
}

int main() {
    int fallos_elegidos{0};
    if (!verificar({}, 4, 0)) { ++fallos_elegidos; }
    if (!verificar({1, 2}, 3, 0)) { ++fallos_elegidos; }
    if (!verificar({4, 4}, 4, 2)) { ++fallos_elegidos; }
    if (!verificar({3, 4, 4, 5}, 4, 3)) { ++fallos_elegidos; }
    std::cout << "Fallos elegidos:" << fallos_elegidos << '\n';
    std::mt19937 motor{229};
    std::uniform_int_distribution<int> tamanos{0, 12};
    std::uniform_int_distribution<int> minimos{0, 9};
    std::uniform_int_distribution<int> valores{0, 9};
    int fallos_generados{0};
    for (int intento{0}; intento < 40; ++intento) {
        const int cantidad = tamanos(motor);
        const int minimo = minimos(motor);
        std::vector<int> datos;
        for (int i{0}; i < cantidad; ++i) {
            datos.push_back(valores(motor));
        }
        const int real = contar_desde(datos, minimo);
        const int esperado = esperado_por_descartes(datos, minimo);
        if (real != esperado) {
            ++fallos_generados;
            std::cout << "Caso:" << intento << ";Minimo:" << minimo << ";Datos:";
            for (int dato : datos) { std::cout << '[' << dato << ']'; }
            std::cout << '\n';
        }
    }
    std::cout << "Fallos generados:" << fallos_generados;
    return 0;
}

#include <iostream>
