int contar_estricto(const std::vector<int>& datos, int minimo) {
    int cantidad{0};
    for (int dato : datos) {
        if (dato > minimo) { ++cantidad; }
    }
    return cantidad;
}

int main() {
    const std::vector<int> datos{1, 4, 4, 9};
    const int real = contar_estricto(datos, 4);
    const int esperado{3};
    std::cout << "Real:" << real << ";Esperado:" << esperado;
    std::cout << ";Coincide:" << (real == esperado);
